CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SEQUENCE IF NOT EXISTS ventas_codigo_seq START 1;
CREATE TABLE IF NOT EXISTS categorias(categoria_id BIGSERIAL PRIMARY KEY,nombre VARCHAR(100) NOT NULL UNIQUE,descripcion TEXT,estado BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS marcas(marca_id BIGSERIAL PRIMARY KEY,nombre VARCHAR(100) NOT NULL UNIQUE,estado BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS unidades_medida(unidad_id BIGSERIAL PRIMARY KEY,nombre VARCHAR(60) NOT NULL UNIQUE,sigla VARCHAR(12) NOT NULL UNIQUE,estado BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS impuestos(impuesto_id BIGSERIAL PRIMARY KEY,nombre VARCHAR(80) NOT NULL,porcentaje NUMERIC(6,3) NOT NULL DEFAULT 0 CHECK(porcentaje>=0),estado BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS productos(producto_id BIGSERIAL PRIMARY KEY,sku VARCHAR(50) NOT NULL UNIQUE,codigo_barras VARCHAR(80) UNIQUE,nombre VARCHAR(180) NOT NULL,descripcion TEXT,categoria_id BIGINT REFERENCES categorias,marca_id BIGINT REFERENCES marcas,unidad_base_id BIGINT NOT NULL REFERENCES unidades_medida,impuesto_id BIGINT NOT NULL REFERENCES impuestos,estado BOOLEAN NOT NULL DEFAULT TRUE,fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS variantes_producto(variante_id BIGSERIAL PRIMARY KEY,producto_id BIGINT NOT NULL REFERENCES productos,sku VARCHAR(60) UNIQUE,nombre VARCHAR(120) NOT NULL,atributos JSONB NOT NULL DEFAULT '{}',estado BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(variante_id,producto_id));
CREATE TABLE IF NOT EXISTS producto_unidad(producto_unidad_id BIGSERIAL PRIMARY KEY,producto_id BIGINT NOT NULL REFERENCES productos,unidad_id BIGINT NOT NULL REFERENCES unidades_medida,factor_conversion NUMERIC(14,4) NOT NULL CHECK(factor_conversion>0),UNIQUE(producto_id,unidad_id));
CREATE TABLE IF NOT EXISTS tipos_documento_identidad(tipo_documento_id BIGSERIAL PRIMARY KEY,codigo VARCHAR(12) UNIQUE NOT NULL,nombre VARCHAR(60) NOT NULL);
CREATE TABLE IF NOT EXISTS clientes(cliente_id BIGSERIAL PRIMARY KEY,tipo_documento VARCHAR(20) NOT NULL,numero_documento VARCHAR(20) NOT NULL UNIQUE,razon_social_nombres VARCHAR(180) NOT NULL,nombre_comercial VARCHAR(180),email VARCHAR(160),telefono VARCHAR(40),direccion TEXT,limite_credito NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK(limite_credito>=0),dias_credito INTEGER NOT NULL DEFAULT 0,estado BOOLEAN NOT NULL DEFAULT TRUE,fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS proveedores(proveedor_id BIGSERIAL PRIMARY KEY,tipo_documento VARCHAR(20) NOT NULL,numero_documento VARCHAR(20) NOT NULL UNIQUE,razon_social VARCHAR(180) NOT NULL,nombre_comercial VARCHAR(180),contacto VARCHAR(120),email VARCHAR(160),telefono VARCHAR(40),direccion TEXT,estado BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS sedes(sede_id BIGSERIAL PRIMARY KEY,nombre VARCHAR(100) NOT NULL UNIQUE,direccion TEXT,ciudad VARCHAR(100) NOT NULL DEFAULT 'Nuevo Chimbote',estado BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS almacenes(almacen_id BIGSERIAL PRIMARY KEY,sede_id BIGINT NOT NULL REFERENCES sedes,nombre VARCHAR(100) NOT NULL,estado BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(sede_id,nombre));
CREATE TABLE IF NOT EXISTS precios_producto(precio_id BIGSERIAL PRIMARY KEY,producto_id BIGINT NOT NULL REFERENCES productos,precio_venta NUMERIC(14,2) NOT NULL CHECK(precio_venta>=0),fecha_inicio DATE NOT NULL DEFAULT CURRENT_DATE,fecha_fin DATE,UNIQUE(producto_id,fecha_inicio));
CREATE TABLE IF NOT EXISTS inventarios(inventario_id BIGSERIAL PRIMARY KEY,producto_id BIGINT NOT NULL REFERENCES productos,variante_id BIGINT,almacen_id BIGINT NOT NULL REFERENCES almacenes,stock_actual NUMERIC(14,3) NOT NULL DEFAULT 0 CHECK(stock_actual>=0),stock_minimo NUMERIC(14,3) NOT NULL DEFAULT 0 CHECK(stock_minimo>=0),stock_maximo NUMERIC(14,3) NOT NULL DEFAULT 0 CHECK(stock_maximo>=0),ubicacion VARCHAR(100),actualizado_en TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(variante_id,producto_id) REFERENCES variantes_producto(variante_id,producto_id),UNIQUE NULLS NOT DISTINCT(producto_id,variante_id,almacen_id));
CREATE TABLE IF NOT EXISTS empleados(empleado_id BIGSERIAL PRIMARY KEY,nombres VARCHAR(100) NOT NULL,apellidos VARCHAR(120) NOT NULL,documento VARCHAR(20) UNIQUE,telefono VARCHAR(40),email VARCHAR(160),cargo VARCHAR(100),estado BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS usuarios(usuario_id BIGSERIAL PRIMARY KEY,empleado_id BIGINT REFERENCES empleados,nombre_usuario VARCHAR(80) NOT NULL UNIQUE,contrasena_hash TEXT NOT NULL,activo BOOLEAN NOT NULL DEFAULT TRUE,sede_id BIGINT REFERENCES sedes,ultimo_acceso TIMESTAMPTZ,fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS roles(rol_id BIGSERIAL PRIMARY KEY,nombre VARCHAR(80) NOT NULL UNIQUE,descripcion TEXT);
CREATE TABLE IF NOT EXISTS usuario_rol(usuario_id BIGINT NOT NULL REFERENCES usuarios,rol_id BIGINT NOT NULL REFERENCES roles,PRIMARY KEY(usuario_id,rol_id));
CREATE TABLE IF NOT EXISTS logs_auditoria(log_id BIGSERIAL PRIMARY KEY,usuario_id BIGINT REFERENCES usuarios,accion VARCHAR(100) NOT NULL,tabla_afectada VARCHAR(100) NOT NULL,registro_id BIGINT,valores_anteriores JSONB,valores_nuevos JSONB,ip VARCHAR(60),fecha_hora TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cajas(caja_id BIGSERIAL PRIMARY KEY,sede_id BIGINT NOT NULL REFERENCES sedes,nombre VARCHAR(100) NOT NULL,estado BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS caja_sesiones(sesion_id BIGSERIAL PRIMARY KEY,caja_id BIGINT NOT NULL REFERENCES cajas,usuario_apertura BIGINT NOT NULL REFERENCES usuarios,usuario_cierre BIGINT REFERENCES usuarios,monto_inicial NUMERIC(14,2) NOT NULL,monto_final NUMERIC(14,2),diferencia NUMERIC(14,2),abierta_en TIMESTAMPTZ NOT NULL DEFAULT now(),cerrada_en TIMESTAMPTZ,estado VARCHAR(20) NOT NULL DEFAULT 'ABIERTA');
CREATE TABLE IF NOT EXISTS metodos_pago(metodo_pago_id BIGSERIAL PRIMARY KEY,nombre VARCHAR(60) NOT NULL UNIQUE,estado BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS tipos_comprobante(tipo_comprobante_id BIGSERIAL PRIMARY KEY,nombre VARCHAR(40) NOT NULL UNIQUE,codigo VARCHAR(8) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS ventas(venta_id BIGSERIAL PRIMARY KEY,codigo_venta VARCHAR(40) NOT NULL UNIQUE,sede_id BIGINT NOT NULL REFERENCES sedes,almacen_id BIGINT NOT NULL REFERENCES almacenes,cliente_id BIGINT NOT NULL REFERENCES clientes,empleado_id BIGINT REFERENCES empleados,usuario_id BIGINT NOT NULL REFERENCES usuarios,condicion_pago VARCHAR(20) NOT NULL CHECK(condicion_pago IN('CONTADO','CREDITO')),fecha_venta TIMESTAMPTZ NOT NULL DEFAULT now(),subtotal NUMERIC(14,2) NOT NULL,impuesto_total NUMERIC(14,2) NOT NULL DEFAULT 0,monto_total NUMERIC(14,2) NOT NULL,estado VARCHAR(20) NOT NULL DEFAULT 'COMPLETADA');
CREATE TABLE IF NOT EXISTS detalle_venta(detalle_venta_id BIGSERIAL PRIMARY KEY,venta_id BIGINT NOT NULL REFERENCES ventas,producto_id BIGINT NOT NULL REFERENCES productos,variante_id BIGINT,cantidad NUMERIC(14,3) NOT NULL CHECK(cantidad>0),precio_unitario NUMERIC(14,2) NOT NULL,descuento NUMERIC(14,2) NOT NULL DEFAULT 0,impuesto NUMERIC(14,2) NOT NULL DEFAULT 0,subtotal NUMERIC(14,2) NOT NULL,FOREIGN KEY(variante_id,producto_id) REFERENCES variantes_producto(variante_id,producto_id));
CREATE TABLE IF NOT EXISTS comprobantes(comprobante_id BIGSERIAL PRIMARY KEY,venta_id BIGINT NOT NULL UNIQUE REFERENCES ventas,tipo_comprobante_id BIGINT NOT NULL REFERENCES tipos_comprobante,serie VARCHAR(12) NOT NULL,numero VARCHAR(24) NOT NULL,fecha_emision TIMESTAMPTZ NOT NULL DEFAULT now(),estado VARCHAR(20) NOT NULL DEFAULT 'EMITIDO',UNIQUE(serie,numero));
CREATE TABLE IF NOT EXISTS pagos(pago_id BIGSERIAL PRIMARY KEY,venta_id BIGINT NOT NULL REFERENCES ventas,metodo_pago_id BIGINT NOT NULL REFERENCES metodos_pago,monto NUMERIC(14,2) NOT NULL CHECK(monto>=0),usuario_id BIGINT REFERENCES usuarios,fecha_pago TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notas_credito(nota_credito_id BIGSERIAL PRIMARY KEY,venta_id BIGINT NOT NULL REFERENCES ventas,comprobante_id BIGINT REFERENCES comprobantes,motivo TEXT NOT NULL,monto NUMERIC(14,2) NOT NULL,fecha_emision TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS compras(compra_id BIGSERIAL PRIMARY KEY,codigo_compra VARCHAR(40) UNIQUE NOT NULL,proveedor_id BIGINT NOT NULL REFERENCES proveedores,sede_id BIGINT NOT NULL REFERENCES sedes,almacen_id BIGINT NOT NULL REFERENCES almacenes,usuario_id BIGINT NOT NULL REFERENCES usuarios,fecha_compra TIMESTAMPTZ NOT NULL DEFAULT now(),subtotal NUMERIC(14,2) NOT NULL,impuesto_total NUMERIC(14,2) NOT NULL DEFAULT 0,flete NUMERIC(14,2) NOT NULL DEFAULT 0,monto_total NUMERIC(14,2) NOT NULL,condicion_pago VARCHAR(20) NOT NULL DEFAULT 'CONTADO',estado VARCHAR(20) NOT NULL DEFAULT 'RECIBIDA');
CREATE TABLE IF NOT EXISTS detalle_compra(detalle_compra_id BIGSERIAL PRIMARY KEY,compra_id BIGINT NOT NULL REFERENCES compras,producto_id BIGINT NOT NULL REFERENCES productos,variante_id BIGINT,cantidad NUMERIC(14,3) NOT NULL CHECK(cantidad>0),costo_unitario NUMERIC(14,2) NOT NULL,impuesto NUMERIC(14,2) NOT NULL DEFAULT 0,subtotal NUMERIC(14,2) NOT NULL,FOREIGN KEY(variante_id,producto_id) REFERENCES variantes_producto(variante_id,producto_id));
CREATE TABLE IF NOT EXISTS cuentas_por_cobrar(cuenta_id BIGSERIAL PRIMARY KEY,venta_id BIGINT NOT NULL UNIQUE REFERENCES ventas,monto_total NUMERIC(14,2) NOT NULL,saldo_pendiente NUMERIC(14,2) NOT NULL,fecha_emision DATE NOT NULL DEFAULT CURRENT_DATE,fecha_vencimiento DATE NOT NULL,estado VARCHAR(20) NOT NULL DEFAULT 'PENDIENTE');
CREATE TABLE IF NOT EXISTS pagos_cuenta_cobrar(pago_cuenta_id BIGSERIAL PRIMARY KEY,cuenta_id BIGINT NOT NULL REFERENCES cuentas_por_cobrar,metodo_pago_id BIGINT NOT NULL REFERENCES metodos_pago,monto NUMERIC(14,2) NOT NULL CHECK(monto>0),usuario_id BIGINT REFERENCES usuarios,fecha_pago TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS movimientos_inventario(movimiento_id BIGSERIAL PRIMARY KEY,producto_id BIGINT NOT NULL REFERENCES productos,variante_id BIGINT REFERENCES variantes_producto,almacen_id BIGINT NOT NULL REFERENCES almacenes,usuario_id BIGINT REFERENCES usuarios,tipo_movimiento VARCHAR(40) NOT NULL,cantidad NUMERIC(14,3) NOT NULL CHECK(cantidad>0),costo_unitario NUMERIC(14,2) NOT NULL DEFAULT 0,fecha_movimiento TIMESTAMPTZ NOT NULL DEFAULT now(),referencia VARCHAR(120),observacion TEXT);
CREATE TABLE IF NOT EXISTS motivos_devolucion(motivo_id BIGSERIAL PRIMARY KEY,nombre VARCHAR(100) NOT NULL UNIQUE,estado BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS devoluciones(devolucion_id BIGSERIAL PRIMARY KEY,tipo VARCHAR(20) NOT NULL CHECK(tipo IN('VENTA','COMPRA')),venta_id BIGINT REFERENCES ventas,compra_id BIGINT REFERENCES compras,cliente_id BIGINT REFERENCES clientes,proveedor_id BIGINT REFERENCES proveedores,empleado_id BIGINT REFERENCES empleados,usuario_id BIGINT REFERENCES usuarios,motivo_id BIGINT REFERENCES motivos_devolucion,fecha TIMESTAMPTZ NOT NULL DEFAULT now(),motivo TEXT NOT NULL,monto NUMERIC(14,2) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS detalle_devoluciones(detalle_devolucion_id BIGSERIAL PRIMARY KEY,devolucion_id BIGINT NOT NULL REFERENCES devoluciones,producto_id BIGINT NOT NULL REFERENCES productos,variante_id BIGINT REFERENCES variantes_producto,almacen_id BIGINT NOT NULL REFERENCES almacenes,cantidad NUMERIC(14,3) NOT NULL CHECK(cantidad>0),monto NUMERIC(14,2) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS analytics_predictions(prediction_id BIGSERIAL PRIMARY KEY,producto_id BIGINT NOT NULL REFERENCES productos,variante_id BIGINT REFERENCES variantes_producto,sede_id BIGINT REFERENCES sedes,periodo_inicio DATE NOT NULL,periodo_fin DATE NOT NULL,demanda_estimada NUMERIC(14,3) NOT NULL CHECK(demanda_estimada>=0),metodo VARCHAR(40) NOT NULL,datos_base JSONB NOT NULL DEFAULT '{}',generado_en TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(periodo_fin>=periodo_inicio));
CREATE INDEX IF NOT EXISTS idx_predictions_product_period ON analytics_predictions(producto_id,variante_id,sede_id,periodo_inicio DESC);
CREATE INDEX IF NOT EXISTS idx_inventarios_almacen ON inventarios(almacen_id,producto_id);
CREATE INDEX IF NOT EXISTS idx_ventas_fecha_sede ON ventas(fecha_venta,sede_id);
CREATE INDEX IF NOT EXISTS idx_movimientos_kardex ON movimientos_inventario(almacen_id,producto_id,fecha_movimiento DESC);
CREATE INDEX IF NOT EXISTS idx_auditoria_fecha ON logs_auditoria(fecha_hora DESC);
CREATE OR REPLACE FUNCTION vecor_check_venta_almacen() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM almacenes WHERE almacen_id=NEW.almacen_id AND sede_id=NEW.sede_id) THEN RAISE EXCEPTION 'El almacén no pertenece a la sede de la venta'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_venta_almacen ON ventas;
CREATE TRIGGER trg_venta_almacen BEFORE INSERT OR UPDATE OF almacen_id,sede_id ON ventas FOR EACH ROW EXECUTE FUNCTION vecor_check_venta_almacen();
CREATE OR REPLACE FUNCTION vecor_check_compra_almacen() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM almacenes WHERE almacen_id=NEW.almacen_id AND sede_id=NEW.sede_id) THEN RAISE EXCEPTION 'El almacén no pertenece a la sede de la compra'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_compra_almacen ON compras;
CREATE TRIGGER trg_compra_almacen BEFORE INSERT OR UPDATE OF almacen_id,sede_id ON compras FOR EACH ROW EXECUTE FUNCTION vecor_check_compra_almacen();
CREATE OR REPLACE FUNCTION vecor_audit_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Los registros de auditoría son inmutables'; END $$;
DROP TRIGGER IF EXISTS trg_audit_immutable ON logs_auditoria;
CREATE TRIGGER trg_audit_immutable BEFORE UPDATE OR DELETE ON logs_auditoria FOR EACH ROW EXECUTE FUNCTION vecor_audit_immutable();
